schema:
{
  "description": "Rendiconti acquisti in PDF",
  "baseAnalyzerId": "prebuilt-document",
  "fieldSchema": {
    "fields": {
      "Totale": {
        "type": "number",
        "method": "extract",
        "estimateSourceAndConfidence": true,
        "description": "Valore dopo \"Totale complessivo\", in fondo all'ultima pagina; non i subtotali di pagina."
      },
      "Righe": {
        "type": "array",
        "description": "Tutte le righe della tabella, anche quando continua sulla pagina successiva.",
        "items": {
          "type": "object",
          "properties": {
            "Codice": {
              "type": "string"
            },
            "Quantita": {
              "type": "number"
            },
            "Prezzo": {
              "type": "number"
            }
          }
        }
      }
    }
  }
}
